package com.rescuefly.controller;
import com.rescuefly.dto.AuthDtos.*; import com.rescuefly.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/register") public ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.register(r));}@PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);}}
